'use strict';
window.AccountManager={
 user:null,csrf:null,profiles:[],active:null,revision:0,ack:'',timer:null,busy:null,blocked:false,loading:false,syncLabel:'访客 · 本机保存',authMode:'login',pending:false,
 storageKey(){return this.user?`${KEY}:${this.user.id}:${this.active?.id||'unselected'}`:KEY;},
 async api(route,method='GET',data){const headers={};if(data!==undefined)headers['Content-Type']='application/json';if(this.csrf)headers['X-CSRF-Token']=this.csrf;const res=await fetch(route,{method,headers,credentials:'same-origin',body:data===undefined?undefined:JSON.stringify(data),signal:AbortSignal.timeout(10000)});const value=await res.json();if(!res.ok)throw Object.assign(new Error(value.error||'服务暂时不可用。'),{status:res.status});return value;},
 updateHeader(){const p=this.active;$('#account-header').textContent=this.user?`${p?.avatar||'♙'} ${p?.name||this.user.username}`:'♙ 家长登录';$('#welcome-text').textContent=p?`你好，${p.name} 👋`:'你好，小小探险家 👋';$('#sync-status').textContent=this.syncLabel;$('#sync-status').classList.toggle('sync-error',this.blocked);$('#storage-note').textContent=this.user?'按孩子档案保存进度 · 照片与声音陪练':'访客进度保存在本机 · 照片与声音陪练';},
 status(label){this.syncLabel=label;this.updateHeader();},
 queueSave(){if(!this.user||!this.active||this.loading)return;const text=JSON.stringify(state);if(text===this.ack)return;this.pending=true;if(this.blocked){this.status('未同步 · 请处理');return;}this.status('正在保存…');clearTimeout(this.timer);this.timer=setTimeout(()=>this.flush(),350);},
 async flush(){clearTimeout(this.timer);if(this.busy)return this.busy;if(!this.user||!this.active||this.loading)return true;if(this.blocked)return false;if(JSON.stringify(state)===this.ack){this.pending=false;return true;}
  this.busy=(async()=>{try{while(JSON.stringify(state)!==this.ack){const text=JSON.stringify(state),id=this.active.id;this.status('正在保存…');const result=await this.api(`/api/profiles/${id}/progress`,'PUT',{data:JSON.parse(text),revision:this.revision});this.revision=result.revision;this.ack=text;this.active.updatedAt=result.updatedAt;this.active.stats={stars:state.stars,rounds:state.rounds,weak:weakWords().length};}this.pending=false;this.status('已保存到服务器');return true;}catch(e){this.blocked=true;try{localStorage.setItem(this.storageKey()+':recovery',JSON.stringify(state));}catch{}this.status(e.status===409?'记录冲突 · 请处理':'未同步 · 本机已保留');toast(e.status===401?'登录已过期，本机已保留未同步记录。':e.message||'网络中断，记录已保留在本机，可稍后重试。');return false;}finally{this.busy=null;}})();return this.busy;
 },
 async fetchProfiles(){this.profiles=(await this.api('/api/profiles')).profiles;},
 async selectProfile(id,skipFlush=false){if(!skipFlush&&!await this.flush())return false;const p=this.profiles.find(p=>p.id===id&&!p.archived);if(!p)return false;this.loading=true;this.status('正在载入…');try{const result=await this.api(`/api/profiles/${id}/progress`);const clean=validateState(result.data);this.active=p;this.revision=result.revision;this.blocked=false;this.pending=false;this.ack=JSON.stringify(clean);state=clean;try{localStorage.setItem(`${KEY}:last:${this.user.id}`,id);}catch{}this.status('已保存到服务器');render();return true;}catch(e){toast(e.message||'载入失败，原来的进度仍保留。');return false;}finally{this.loading=false;}},
 async signedIn(result){this.user=result.user;this.csrf=result.csrf;this.active=null;this.blocked=false;await this.fetchProfiles();let last=null;try{last=localStorage.getItem(`${KEY}:last:${this.user.id}`);}catch{}const p=this.profiles.find(p=>p.id===last&&!p.archived)||this.profiles.find(p=>!p.archived);if(p)await this.selectProfile(p.id,true);else{state=fresh();this.status('请选择孩子档案');render();}},
 async init(){try{const result=await this.api('/api/auth/me');if(result.user)await this.signedIn(result);else this.updateHeader();}catch{this.status('账号服务暂不可用');}if(page==='account')render();},
 pageHTML(){
  if(!this.user)return `<div class="page-heading"><span class="eyebrow">FAMILY LEARNING SPACE</span><h1>家长账号与学习数据</h1><p>一个家长账号，管理多个孩子。每个孩子有自己的薄弱词、星星与进度。</p></div><section class="account-panel"><div class="auth-tabs"><button class="filter-chip ${this.authMode==='login'?'selected':''}" data-auth-mode="login">登录</button><button class="filter-chip ${this.authMode==='register'?'selected':''}" data-auth-mode="register">创建家长账号</button></div><form id="auth-form"><label>家长账号<input name="username" autocomplete="username" required minlength="3" maxlength="32" pattern="[a-zA-Z0-9_.-]{3,32}" placeholder="英文字母或数字，如 happy_family"></label><label>密码<input name="password" type="password" autocomplete="${this.authMode==='login'?'current-password':'new-password'}" required minlength="8" maxlength="128" placeholder="至少 8 个字符"></label>${this.authMode==='register'?'<label>第一个孩子的昵称<input name="childName" required maxlength="24" placeholder="如 小豆豆"></label>':''}<p id="auth-error" class="form-error" role="alert"></p><button class="primary" type="submit">${this.authMode==='login'?'登录并载入进度':'创建账号与孩子档案'}</button></form><div class="info-box">无需邮箱或孩子真实姓名。账号与学习记录保存在当前网站的服务器；其他设备打开同一网址并登录，即可继续学习。<br>之前的访客记录不会自动覆盖，登录后可导入为一个新档案。</div></section>`;
  const cards=this.profiles.map(p=>{const stats=p.id===this.active?.id?{stars:state.stars,rounds:state.rounds,weak:weakWords().length}:p.stats;return `<article class="profile-card ${p.id===this.active?.id?'current':''} ${p.archived?'archived':''}"><div class="profile-avatar">${p.avatar}</div><h3>${esc(p.name)}${p.archived?' · 已归档':''}</h3><p>${stats.stars} 颗星 · ${stats.rounds} 轮 · ${stats.weak} 个薄弱词</p><p class="small muted">${p.id===this.active?.id?'正在使用此档案':'数据单独保存'}</p><div class="button-row">${p.archived?`<button class="secondary" data-restore-profile="${p.id}">恢复档案</button>`:`<button class="primary" data-switch-profile="${p.id}" ${p.id===this.active?.id?'disabled':''}>${p.id===this.active?.id?'当前孩子':'切换到此孩子'}</button><button class="secondary" data-edit-profile="${p.id}">编辑</button>`}</div></article>`;}).join('');
  let guest=false,recovery=false;try{const raw=localStorage.getItem(KEY);if(raw){const old=validateState(JSON.parse(raw));guest=Object.keys(old.words).length>0||old.rounds>0;}recovery=!!localStorage.getItem(this.storageKey()+':recovery');}catch{}
  return `<div class="page-heading"><span class="eyebrow">FAMILY LEARNING SPACE</span><h1>账号与学习数据</h1><p>家长账号：<strong>${esc(this.user.username)}</strong> · 每个孩子的数据分别保存。</p></div><div class="account-actions"><span class="sync-badge ${this.blocked?'error':''}">${esc(this.syncLabel)}</span><button class="secondary" id="account-refresh">${this.blocked?'重新载入服务器记录':'刷新档案'}</button>${this.blocked?'<button class="secondary" id="sync-retry">重试保存本机进度</button>':''}<button class="secondary" id="export-btn">导出当前孩子记录</button>${recovery?'<button class="secondary" id="export-recovery">导出本机恢复备份</button>':''}<button class="text-btn" id="logout-btn">退出登录</button></div>${this.blocked?'<div class="info-box">本机的未同步记录已保留。记录冲突时，可先导出备份再重新载入；重试不会覆盖另一台设备的更新。</div>':''}${guest?'<div class="migration-banner"><span>原来的访客学习记录仍在这台浏览器里。</span><button class="secondary" id="migrate-guest">导入为新孩子档案</button></div>':''}<div class="profile-grid">${cards}</div><section class="account-panel" style="margin-top:24px"><h2>添加孩子档案</h2><form id="profile-form"><div class="profile-form-row"><label>孩子昵称<input name="name" required maxlength="24" placeholder="例如：小豆豆"></label><label>头像<select name="avatar">${['🦉','🐼','🦊','🐰','🐱','🐶','🐯','🐸'].map(a=>`<option>${a}</option>`).join('')}</select></label></div><p class="form-error" id="profile-error" role="alert"></p><button class="primary" type="submit">添加档案</button></form></section><div class="info-box">学习记录自动保存。要导入 JSON 备份，请先切换到对应孩子，再打开“家长设置”。归档会保留记录，之后可以恢复。<br>录音不进入账号数据，也不上传到服务器。</div>`;
 },
 async logout(){await this.flush();try{await this.api('/api/auth/logout','POST',{});}catch(e){if(e.status!==401){toast('退出失败，请检查网络后再试。');return;}}this.user=null;this.csrf=null;this.active=null;this.ack='';this.blocked=false;this.pending=false;state=fresh();try{const raw=localStorage.getItem(KEY);if(raw)state=validateState(JSON.parse(raw));}catch{}this.status('访客 · 本机保存');render();toast('已退出，孩子档案仍保存在服务器。');},
 async reloadServer(){if(!this.user)return;try{if(this.active){localStorage.setItem(this.storageKey()+':recovery',JSON.stringify(state));}await this.fetchProfiles();if(this.active)await this.selectProfile(this.active.id,true);render();}catch(e){toast(e.message||'载入失败，请稍后重试。');}},
 editProfile(id){const p=this.profiles.find(p=>p.id===id);if(!p)return;$('#profile-edit-content').innerHTML=`<div class="modal-top"><h2>编辑孩子档案</h2><button class="icon-btn" data-close="profile-edit-dialog" aria-label="关闭编辑">✕</button></div><form id="profile-edit-form" data-id="${id}"><label>孩子昵称<input name="name" value="${esc(p.name)}" required maxlength="24"></label><label>头像<select name="avatar">${['🦉','🐼','🦊','🐰','🐱','🐶','🐯','🐸'].map(a=>`<option ${a===p.avatar?'selected':''}>${a}</option>`).join('')}</select></label><p class="form-error" id="edit-error" role="alert"></p><button class="primary" type="submit">保存修改</button></form><div class="info-box">归档只隐藏档案，学习数据仍保留，可在账号页恢复。</div><button class="text-btn" data-archive-profile="${id}" ${this.profiles.filter(p=>!p.archived).length<=1?'disabled':''}>归档这个孩子（保留数据）</button>`;$('#profile-edit-dialog').showModal();}
};
const account=window.AccountManager;
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['auth-form','profile-form','profile-edit-form'].includes(form.id))return;e.preventDefault();const b=form.querySelector('button[type="submit"]');b.disabled=true;const data=Object.fromEntries(new FormData(form));const error=$('#'+({ 'auth-form':'auth-error','profile-form':'profile-error','profile-edit-form':'edit-error'}[form.id]));if(error)error.textContent='';
 try{if(form.id==='auth-form'){const result=await account.api('/api/auth/'+account.authMode,'POST',data);form.reset();await account.signedIn(result);toast('已登录。选一个孩子，开始学习吧！');}
  else if(form.id==='profile-form'){if(!await account.flush())throw Error('请先处理未同步记录。');const result=await account.api('/api/profiles','POST',data);await account.fetchProfiles();await account.selectProfile(result.id,true);toast('新档案已创建，各自保存进度。');}
  else{if(!await account.flush())throw Error('请先处理未同步记录。');await account.api('/api/profiles/'+form.dataset.id,'PATCH',data);await account.fetchProfiles();account.active=account.profiles.find(p=>p.id===account.active?.id)||null;account.updateHeader();$('#profile-edit-dialog').close();render();toast('档案已更新。');}
 }catch(err){if(error)error.textContent=err.message||'请求失败，请稍后再试。';}finally{b.disabled=false;}
});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.authMode){account.authMode=b.dataset.authMode;render();return;}
 if(b.dataset.editProfile){account.editProfile(b.dataset.editProfile);return;}
 if(b.id==='logout-btn'){b.disabled=true;await account.logout();return;}
 if(b.id==='account-refresh'){await account.flush();await account.reloadServer();return;}
 if(b.id==='sync-retry'){account.blocked=false;await account.flush();render();return;}
 if(b.id==='export-recovery'){try{const raw=localStorage.getItem(account.storageKey()+':recovery');if(!raw)throw Error();const data=validateState(JSON.parse(raw)),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='单词大闯关-本机恢复备份.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{toast('没有找到可导出的恢复备份。');}return;}
 if(b.dataset.switchProfile){b.disabled=true;cleanupRecording();releaseAudio();await account.selectProfile(b.dataset.switchProfile);render();return;}
 if(b.dataset.archiveProfile||b.dataset.restoreProfile){b.disabled=true;try{if(!await account.flush())throw Error('请先处理未同步记录。');const id=b.dataset.archiveProfile||b.dataset.restoreProfile;await account.api('/api/profiles/'+id,'PATCH',{archived:!!b.dataset.archiveProfile});await account.fetchProfiles();if($('#profile-edit-dialog').open)$('#profile-edit-dialog').close();if(account.active?.id===id&&b.dataset.archiveProfile){const next=account.profiles.find(p=>!p.archived);if(next)await account.selectProfile(next.id,true);}render();toast(b.dataset.archiveProfile?'档案已归档，数据仍保留。':'档案已恢复。');}catch(err){toast(err.message||'更新失败，请稍后重试。');b.disabled=false;}return;}
 if(b.id==='migrate-guest'){b.disabled=true;try{if(!await account.flush())throw Error('请先处理未同步记录。');const guest=validateState(JSON.parse(localStorage.getItem(KEY)));const result=await account.api('/api/profiles','POST',{name:'原本学习记录',avatar:'🦉'});await account.fetchProfiles();if(!await account.selectProfile(result.id,true))throw Error('新档案载入失败，原记录仍保留。');state=guest;save();if(!await account.flush()){render();throw Error('导入记录已保留在本机，请处理未同步记录。');}render();toast('原本记录已导入新档案，访客备份仍保留。');}catch(err){toast(err.message||'导入失败，原记录仍保留。');b.disabled=false;}}
});
window.addEventListener('beforeunload',e=>{if(account.user&&(account.pending||account.busy||account.blocked)){e.preventDefault();e.returnValue='';}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')account.flush();});
account.init();
